@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class AuthorPosition {
  + position : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" ScientificArticle : authors
Person "1" -- "*" ScientificArticle : reviews
Person "*" -- "1" Institution : works for
Institution "1" -- "*" TechnicalReport : publishes
Publisher "1" -- "*" Journal : publishes
Institution "1" -- "*" Journal : subscribes to
Journal "1" -- "*" PeerReviewedPaper : publishes

ScientificArticle "1" -- "*" AuthorPosition
AuthorPosition "*" -- "1" Person : author

@enduml

